import{_ as a,H as e,f as n,i}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"18 | VPN：怎样构建安全的企业网络？","description":"","frontmatter":{},"headers":[{"level":2,"title":"VPN 原理","slug":"vpn-原理","link":"#vpn-原理","children":[{"level":3,"title":"VPN 是什么？","slug":"vpn-是什么","link":"#vpn-是什么","children":[]},{"level":3,"title":"怎样既安全又通用？","slug":"怎样既安全又通用","link":"#怎样既安全又通用","children":[]},{"level":3,"title":"IPSec vs WireGuard","slug":"ipsec-vs-wireguard","link":"#ipsec-vs-wireguard","children":[]},{"level":3,"title":"组网","slug":"组网","link":"#组网","children":[]},{"level":3,"title":"关键概念","slug":"关键概念","link":"#关键概念","children":[]}]},{"level":2,"title":"VPN 实战","slug":"vpn-实战","link":"#vpn-实战","children":[{"level":3,"title":"实验设计","slug":"实验设计","link":"#实验设计","children":[]},{"level":3,"title":"开始实战","slug":"开始实战","link":"#开始实战","children":[]},{"level":3,"title":"配置子网","slug":"配置子网","link":"#配置子网","children":[]},{"level":3,"title":"配置 VPN","slug":"配置-vpn","link":"#配置-vpn","children":[]},{"level":3,"title":"配置被保护流量的路由","slug":"配置被保护流量的路由","link":"#配置被保护流量的路由","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"网络架构实战课/18｜VPN：怎样构建安全的企业网络？.md","filePath":"网络架构实战课/18｜VPN：怎样构建安全的企业网络？.md","lastUpdated":1795559478000}'),p={name:"网络架构实战课/18｜VPN：怎样构建安全的企业网络？.md"};function t(l,s,c,o,r,h){return e(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="_18-vpn-怎样构建安全的企业网络" tabindex="-1">18 | VPN：怎样构建安全的企业网络？ <a class="header-anchor" href="#_18-vpn-怎样构建安全的企业网络" aria-label="Permalink to &quot;18 | VPN：怎样构建安全的企业网络？&quot;">​</a></h1><p>你好，我是谢友鹏。</p><p>上节课我们学习了如何通过 TLS 协议在公网中安全传输数据。TLS 协议通过在传输层和应用层之间添加一层安全协议，实现了加密、认证和完整性校验。然而，TLS 更适用于点对点的安全通信场景，对于某些需要更通用解决方案的情况，TLS 并不是最优选择。</p><p>例如，一个公司的多个办公地点希望通过公网连接，形成一个逻辑上的统一网络，不仅需要确保通信的安全性，还希望异地操作能像局域网内一样方便，比如访问远程办公的共享文件夹，而不需要额外的加密配置。此时，VPN（虚拟专用网络）就成为一种理想的解决方案，它通过在网络层建立安全的隧道，既满足了数据加密的需求，又让跨网络的操作更加流畅和便捷。</p><h2 id="vpn-原理" tabindex="-1">VPN 原理 <a class="header-anchor" href="#vpn-原理" aria-label="Permalink to &quot;VPN 原理&quot;">​</a></h2><p>在正式讲解今天的内容之前，需要说明一下，这节课讨论的 VPN 特指工作在 IP 层、具有安全功能的 VPN，不包括基于 SSL 的 VPN（如 OpenVPN）。</p><h3 id="vpn-是什么" tabindex="-1">VPN 是什么？ <a class="header-anchor" href="#vpn-是什么" aria-label="Permalink to &quot;VPN 是什么？&quot;">​</a></h3><p>VPN（Virtual Private Network，虚拟专用网）是一种通过公共网络来安全地扩展专用网络的技术。我画张图来帮助你更直观地理解它的作用。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/1.png" alt=""></a></p><p>如上图所示，VPN 通过在公共网络中创建一个虚拟的、加密的隧道，使用户可以安全地在公共网络上传输数据，仿佛他们的设备直接连接到了专用网络上一样。这种技术不仅提升了专用网络的功能和安全性，还可以让用户在公共网络上访问原本无法直接访问的资源，因此 VPN常被应用于远程办公、跨分支机构组网等场景。</p><h3 id="怎样既安全又通用" tabindex="-1">怎样既安全又通用？ <a class="header-anchor" href="#怎样既安全又通用" aria-label="Permalink to &quot;怎样既安全又通用？&quot;">​</a></h3><p>简单来说，VPN 的核心理念就是“公网私用”。那它是如何做到既安全又通用的呢？其实，其安全机制和 TLS 类似，无外乎是加密、认证、完整性校验和防重放。与 TLS 不同的是，用于企业组网的 VPN 通常不是在传输层和应用层之间插入安全协议，而是在网络层（IP 层）实现了这些功能。</p><p>我画了一张 TLS 和 VPN 在 TCP/IP 模型中的位置和各层的典型协议，方便你更直观地理解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/2.png" alt=""></a></p><p>如上图所示，因为 VPN 工作在网络层，无论上层应用协议是什么（比如应用层是 HTTP、WebSocket、ftp，或比如传输层使用 TCP 或 UDP），所有数据最终都会通过 IP 层传输。因此，VPN 可以对任意基于 IP 的通信进行加密和保护。而不需要像 TLS 那样在每个协议上都要自己再套一层 TLS 的壳。</p><h3 id="ipsec-vs-wireguard" tabindex="-1">IPSec vs WireGuard <a class="header-anchor" href="#ipsec-vs-wireguard" aria-label="Permalink to &quot;IPSec vs WireGuard&quot;">​</a></h3><p>工作在 IP 层的 VPN 协议中，IPSec 协议是目前网络设备中支持最广泛的协议，同时被 Linux之父誉为“艺术品”的 WireGuard 协议也值得关注。我列了个表格对比了两种协议的特性。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/3.png" alt=""></a></p><p>通过以上对比可以看出，IPSec 的优势在于存量网络设备支持较为完善，缺点在于复杂度高。而 WireGuard 优势在于简洁，已经被集成到了 Linux 内核，但是传统的网络设备支持有限。</p><h3 id="组网" tabindex="-1">组网 <a class="header-anchor" href="#组网" aria-label="Permalink to &quot;组网&quot;">​</a></h3><p>对 VPN 有了初步的认识后，我们继续学习其组网知识。不同子网的用户能够像直连到专用网络上一样，跨越公网发送和接收数据，主要归功于 VPN 的加解密功能不在客户端进行，而是通过 VPN 网关来完成。因此，对于用户来说，只需要将流量通过路由引导到 VPN 网关，剩下的隧道建立和加解密等功能都由 VPN 网关处理即可。</p><p>虽然部分 VPN 协议支持传输模式（保留原始 IP，只对 IP 的有效载荷进行加密），但在实际应用中，子网之间的互通一般使用隧道模式，因为隧道模式可以封装完整的 IP 数据包，适用于更广泛的场景。我绘制了一张典型的隧道模式 VPN 组网图供你参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/4.png" alt=""></a></p><p>如图所示，子网 1 和子网 2 通过两个 VPN 网关建立了一个安全的隧道。子网内的设备如果需要与对端子网通信，只需要将目标子网的路由指向本地的 VPN 网关。这样，数据包就会被发送到 VPN 网关，而 VPN 网关会完成数据包的隧道封装和加密。</p><p>接下来，我们看一下隧道模式下数据包的封装变化。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/5.png" alt=""></a></p><p>如上图所示，当子网 1 的设备需要访问子网 2 的设备时，数据包的流转过程如下：</p><ol><li><p>子网 1 的设备通过路由，将报文发送到本地 VPN 网关。</p></li><li><p>VPN 网关接收到数据包后，会对其进行封装。首先，在原始数据包的外层添加一个新的公网 IP 头，指向对端 VPN 网关。然后对原始数据包进行加密，生成隧道报文。</p></li><li><p>封装好的数据包通过公网发送到对端 VPN 网关（通常使用 UDP 协议监听固定端口，比如Wireguard vpn 默认使用 51820 端口，IPSec vpn 默认使用 500 和 4500 端口）。</p></li><li><p>对端 VPN 网关收到报文后，首先进行解封装，移除隧道头。然后解密报文并完成认证检查。</p></li><li><p>解密后的原始数据包会被转发到子网 2 内的目标设备，像普通路由报文一样处理。</p></li></ol><p>整个过程对于子网中的设备来说是完全透明的。它们既不需要额外配置，也无法感知到跨越公网的过程，仿佛只是在一个局域网内通信。</p><p>前面我们是基于子网之间网络打通的场景展开讨论的。对于出差在外的用户，由于无法像子网那样通过固定的 VPN 网关连接到其他子网，他们通常会在自己的终端设备（如笔记本、电脑或手机）上安装 VPN 软件，使自己的设备充当临时的 VPN 客户端网关。通过这种方式，用户可以在外部网络中安全地访问公司内部资源。</p><h3 id="关键概念" tabindex="-1">关键概念 <a class="header-anchor" href="#关键概念" aria-label="Permalink to &quot;关键概念&quot;">​</a></h3><p>无论是通过固定网关的子网连接，还是外部用户的临时接入，本质上都是通过路由将流量引导至 VPN，然后通过 VPN 将流量封装进隧道，穿越公网后发送到目的网络所在的 VPN。</p><p>这里还需要回答几个关键问题：</p><ol><li><p>VPN 网关是怎样知道需要其他 VPN 保护哪些子网流量的？</p></li><li><p>VPN 网关又是怎样知道将哪些流量的请求发往哪些 VPN 的？</p></li><li><p>VPN 网关之间是怎样使用相同的加密、认证等材料的？</p></li></ol><p>这些信息通过 VPN 隧道建立时的 协商（Handshake） 来完成。协商过程主要是为了</p><p>确定使用的加密算法、认证算法、交换双方要保护的子网范围等信息。</p><p>有些 VPN 协议还定义了交换密钥方法，比如 IPsec 协议中的密钥交换协议 ike。这里我们可以看看华为文档中 IPsec 协议中的 IKE（Internet Key Exchange）与 IPsec 的关系图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/6.png" alt=""></a></p><p>图片来自：support.huawei.com</p><p>如上图所示，VPN 隧道建立时，首先会通过 IKE 协议协商出 IKE SA（安全联盟），其中包含密钥。然后，在 IKE SA 的保护下，协商出 IPsec SA，用于加密、认证和保护流量。</p><p>相比之下，WireGuard 协议简化了很多流程，没有密钥协议过程，直接使用预先配置的非对称密钥完成隧道建立。</p><p>不同 VPN 有不同的表达方式，我将一些比较共性和关键的概念列个表格方便你理解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/7.png" alt=""></a></p><h2 id="vpn-实战" tabindex="-1">VPN 实战 <a class="header-anchor" href="#vpn-实战" aria-label="Permalink to &quot;VPN 实战&quot;">​</a></h2><p>如果学完这些理论，你还是有些迷糊，那么我们就继续在实战中学习吧。</p><h3 id="实验设计" tabindex="-1">实验设计 <a class="header-anchor" href="#实验设计" aria-label="Permalink to &quot;实验设计&quot;">​</a></h3><p>首先，我们来看一下今天实验的网络拓扑图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/8.png" alt=""></a></p><p>如上图所示，假设图 172 网段的网络是公共网络。今天的目标是通过配置 VPN，在公共网络（172 网段）上建立安全的加密通道，打通两个子网（10.10.1.0/24 和 10.10.2.0/24）的通信。</p><h3 id="开始实战" tabindex="-1">开始实战 <a class="header-anchor" href="#开始实战" aria-label="Permalink to &quot;开始实战&quot;">​</a></h3><p>子网的配置需要跟你的实验环境进行调整，后面是我自己的实验环境，可以给毛呢做个参考。</p><h3 id="配置子网" tabindex="-1">配置子网 <a class="header-anchor" href="#配置子网" aria-label="Permalink to &quot;配置子网&quot;">​</a></h3><p>首先，我们需要配置两个子网：将 device1 和 vpn1 添加到子网 10.10.1.0/24，device2 和vpn2 添加到另一个子网 10.10.2.0/24。</p><p>让我们来一起完成配置过程。</p><p>第一步，创建子网。</p><p>在虚拟机中添加两个网络，分别属于 10.10.1.0/24 和 10.10.2.0/24 网段。</p><p>具体步骤是这样的。首先，打开 VMware Fusion，进入“设置”-&gt;“网络”。然后，解锁网络配置，点击加号 (+) 来添加一个新的虚拟网络。最后，将子网 IP 和掩码填入。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/9.png" alt=""></a></p><p>第二步，将虚拟机添加到对应的子网。</p><p>依次进入“虚拟机”-“设置”-&gt;“添加网络适配器”，选择刚才创建的虚拟网络。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/10.png" alt=""></a></p><p>此时登陆虚拟机可以看到新配置的虚拟网卡：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ip link show</span></span>
<span class="line"><span>1: lo: &lt;​LOOPBACK,UP,LOWER_UP&gt; mtu 65536 qdisc noqueue state UNKNOWN mode DEFAULT</span></span>
<span class="line"><span>   link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00</span></span>
<span class="line"><span>2: ens33: &lt;​BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc pfifo_fast state UP mo</span></span>
<span class="line"><span>   link/ether 00:0c:29:c8:e2:26 brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>   altname enp2s1</span></span>
<span class="line"><span>3: ens37: &lt;​BROADCAST,MULTICAST&gt; mtu 1500 qdisc noop state DOWN mode DEFAULT group</span></span>
<span class="line"><span>   link/ether 00:50:56:26:eb:0a brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span>   altname enp2s5</span></span></code></pre></div><p>第三步，启动网卡并配置 IP。</p><p>首先用下面命令启动网卡。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ifconfig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ens37</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span></code></pre></div><p>然后用下面命令配置 ip。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ifconfig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ens37</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.10.1.10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> netmask</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 255.255.255.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span></code></pre></div><p>第四步， 四个虚拟机都配置完成后，我们进行简单的网络验证来验证网络连通性。</p><p>此时，device1 与 device2 不通，但在各自子网内部，设备能够互通。而且 vpn1 和 vpn2 之间也能正常互通。我们可以用 ping 验证。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#device1 ping device2 不通</span></span>
<span class="line"><span>$ ping 10.10.2.20</span></span>
<span class="line"><span>PING 10.10.2.20 (10.10.2.20) 56(84) bytes of data.</span></span>
<span class="line"><span>^C</span></span>
<span class="line"><span>--- 10.10.2.20 ping statistics ---</span></span>
<span class="line"><span>4 packets transmitted, 0 received, 100% packet loss, time 3069ms</span></span>
<span class="line"><span>#device1 ping vpn1 能通</span></span>
<span class="line"><span>$ ping 10.10.1.2</span></span>
<span class="line"><span>PING 10.10.1.2 (10.10.1.2) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 10.10.1.2: icmp_seq=1 ttl=64 time=1.33 ms</span></span>
<span class="line"><span>64 bytes from 10.10.1.2: icmp_seq=2 ttl=64 time=1.16 ms</span></span>
<span class="line"><span>#vpn1 ping vpn2 能通</span></span>
<span class="line"><span>$ ping 172.16.253.138</span></span>
<span class="line"><span>PING 172.16.253.138 (172.16.253.138) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 172.16.253.138: icmp_seq=1 ttl=64 time=2.14 ms</span></span>
<span class="line"><span>64 bytes from 172.16.253.138: icmp_seq=2 ttl=64 time=1.21 ms</span></span>
<span class="line"><span>#vpn2 ping device2 能通</span></span>
<span class="line"><span>$ ping 10.10.2.20</span></span>
<span class="line"><span>PING 10.10.2.20 (10.10.2.20) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 10.10.2.20: icmp_seq=1 ttl=64 time=0.859 ms</span></span>
<span class="line"><span>64 bytes from 10.10.2.20: icmp_seq=2 ttl=64 time=1.46 ms</span></span></code></pre></div><h3 id="配置-vpn" tabindex="-1">配置 VPN <a class="header-anchor" href="#配置-vpn" aria-label="Permalink to &quot;配置 VPN&quot;">​</a></h3><p>搞定子网后，我们就可以开始配置 vpn 了。首先安装 wireguard 相关工具。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wireguard-tools</span></span></code></pre></div><p>然后在两个 VPN 上生成各自的私钥和公钥。我已经生成的公私钥为 vpn1 的privatekey和publickey，vpn2 的privatekey和publickey，你也可以直接使用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#生成私钥</span></span>
<span class="line"><span>wg genkey &gt; privatekey</span></span>
<span class="line"><span>#生成公钥</span></span>
<span class="line"><span>wg pubkey &lt; privatekey &gt; publickey</span></span></code></pre></div><p>参照 vpn1 的配置文件 /etc/wireguard/wg0.conf和 vpn2 的配置文件 /etc/wireguard/wg0.conf，进行修改，然后用后面的命令启动 VPN。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo wg-quick up wg0</span></span></code></pre></div><p>两边的 VPN 都启动后，可以查看一下 VPN 的状态。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vpn1:~$ sudo wg show</span></span>
<span class="line"><span>interface: wg0</span></span>
<span class="line"><span> public key: YiL95lWnimaMT4Zj5orOqADBxwf+bLKx3Y7OF5yQ4S8=</span></span>
<span class="line"><span> private key: (hidden)</span></span>
<span class="line"><span> listening port: 51820</span></span>
<span class="line"><span>peer: rZqn0uL9IiNA2sWrVkbTymPiTgpWbBkByTH1/QHBRRA=</span></span>
<span class="line"><span> endpoint: 172.16.253.138:51820</span></span>
<span class="line"><span> allowed ips: 10.10.2.0/24</span></span></code></pre></div><h3 id="配置被保护流量的路由" tabindex="-1">配置被保护流量的路由 <a class="header-anchor" href="#配置被保护流量的路由" aria-label="Permalink to &quot;配置被保护流量的路由&quot;">​</a></h3><p>VPN 隧道建立完成后，我们需要在子网设备上配置路由，使得流量能够通过 VPN 隧道转发到对端子网。如下操作，device1 上配置去对端网段的路由都以 vpn1 为网关。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#device1上配置去10.10.2.0/24网段的流量，都以vpn1为网关</span></span>
<span class="line"><span>$ sudo ip route add 10.10.2.0/24 via 10.10.1.2 dev ens37</span></span>
<span class="line"><span>#验证一下去device2的路由是否生效</span></span>
<span class="line"><span>$ ip route get  10.10.2.20</span></span>
<span class="line"><span>10.10.2.20 via 10.10.1.2 dev ens37 src 10.10.1.10 uid 1000</span></span></code></pre></div><p>同理，device2 上配置去对端网段的路由都以 vpn2 为网关。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#device2上配置去10.10.1.0/24网段的流量，都以vpn2为网关</span></span>
<span class="line"><span>$ sudo ip route add 10.10.1.0/24 via 10.10.2.2 dev ens37</span></span>
<span class="line"><span>#验证一下去device1的路由是否生效</span></span>
<span class="line"><span>$ ip route get 10.10.1.10</span></span>
<span class="line"><span>10.10.1.10 via 10.10.2.2 dev ens37 src 10.10.2.20 uid 1000</span></span>
<span class="line"><span>   cache</span></span></code></pre></div><p>至此，配置结束，我们在 device1 上访问一下 device2，会发现可以连通了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ping 10.10.2.20</span></span>
<span class="line"><span>PING 10.10.2.20 (10.10.2.20) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 10.10.2.20: icmp_seq=1 ttl=62 time=4.47 ms</span></span>
<span class="line"><span>64 bytes from 10.10.2.20: icmp_seq=2 ttl=62 time=3.16 ms</span></span>
<span class="line"><span>64 bytes from 10.10.2.20: icmp_seq=3 ttl=62 time=3.24 ms</span></span>
<span class="line"><span>64 bytes from 10.10.2.20: icmp_seq=4 ttl=62 time=3.22 ms</span></span></code></pre></div><p>如果你想继续观察一下 VPN 报文，使用 sudo wg-quick down wg0 关闭 VPN 功能，然后启动VPN 和流量访问的时候，使用下面命令在 VPN 上抓包。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo tcpdump -i any port 51820 -w wireguard.pcap</span></span></code></pre></div><p>我们可以用 Wireshark 打开抓包文件wireguard.pcap，它并没有暴露子网流量的 IP，还对数据进行了加密。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/11.png" alt=""></a></p><p>好，我们的 VPN 实验到此结束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天的内容就是这些，我给你准备了一个思维导图回顾要点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/12.png" alt=""></a></p><p>这节课我们了解了 VPN 的原理与应用场景。在公共网络中，VPN 通过创建加密隧道，将多个地理位置分散的网络节点逻辑上连接成一个安全的专用网络。这使得跨网络的操作如同在同一局域网内一样便捷。</p><p>然后，我们对比 TLS 和 VPN 工作等网络层，分析了其具备更高的通用性的原因。</p><p>之后，我们对比了两种典型的 VPN 协议：IPsec 和 WireGuard。IPsec 以广泛的设备兼容性见长，但复杂度较高。而 WireGuard 则以简单高效著称，适合现代化需求。再之后，我们学习了 VPN 打通子网场景的组网，还了解了一些关键概念。</p><p>最后，我们将在实践中学习了如何配置 WireGuard VPN 隧道，实现跨子网的互联互通，建议你课后也动手试试看。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>通过这节课的学习，你明白 VPN 的隧道究竟是什么了吗？</p></li><li><p>使用 VPN 的隧道模式从理论上自己的 IP 地址会被包含在隧道里面了，那从管控者的角度出发，还有什么办法知道你的原始 IP 地址吗？</p></li></ol><p>欢迎你在留言区和我交流互动，如果这节课对你有启发，也推荐你分享给身边更多朋友。</p>`,102)])])}const d=a(p,[["render",t]]);export{g as __pageData,d as default};
